import { PointerError, formatPointer, parsePointer, resolveTokens } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const ARRAY_INDEX = /^(0|[1-9][0-9]*)$/;

/**
 * Set an own, enumerable, writable property, bypassing the `__proto__`
 * accessor so that key behaves like any other own property.
 *
 * @param {object} target object to receive the property
 * @param {string} key property name, possibly `__proto__`
 * @param {unknown} value the value to store
 * @returns {void}
 */
function setOwn(target, key, value) {
  Object.defineProperty(target, key, { value, writable: true, enumerable: true, configurable: true });
}

/**
 * Deep-copy a value while verifying it is plain JSON data.
 *
 * @param {unknown} value value to copy
 * @param {string} label name used in the error message ("document" or "value")
 * @returns {unknown} an independent deep copy
 */
function cloneJSON(value, label) {
  if (value === null) return null;
  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') return value;
  if (Array.isArray(value)) return value.map((item) => cloneJSON(item, label));
  if (type === 'object') {
    const out = {};
    for (const key of Object.keys(value)) setOwn(out, key, cloneJSON(value[key], label));
    return out;
  }
  throw new TypeError(`${label} is not JSON data`);
}

/**
 * Compare two JSON values structurally: object members in any order, array
 * elements in order, no type coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether the values are structurally equal
 */
function jsonEquals(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    return a.every((item, i) => jsonEquals(item, b[i]));
  }
  if (a !== null && b !== null && typeof a === 'object') {
    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) return false;
    return aKeys.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEquals(a[key], b[key]));
  }
  return false;
}

