 * Whether `prefix` is a proper prefix of `tokens` (shorter and matching).
 *
 * @param {string[]} prefix candidate prefix tokens
 * @param {string[]} tokens tokens to check against
 * @returns {boolean} true when prefix is strictly shorter and matches
 */
function isProperPrefix(prefix, tokens) {
  if (prefix.length >= tokens.length) return false;
  return prefix.every((token, i) => token === tokens[i]);
