 * Navigate to the container that directly holds the final token.
 *
 * @param {unknown} document root document
 * @param {string[]} tokens full token list, of which all but the last are followed
 * @param {string} pointer the whole pointer, for error reporting
 * @returns {unknown} the parent container
 */
