}

/**
 * Replace the value named by `tokens`, mutating in place, or return `value`
 * itself when the pointer names the whole document.
 *
 * @param {unknown} document root document
 * @param {string[]} tokens decoded reference tokens
 * @param {string} pointer the whole pointer, for error reporting
 * @param {unknown} value already-cloned replacement value
 * @returns {unknown} the (possibly new) document
 */
function replaceAt(document, tokens, pointer, value) {
  if (tokens.length === 0) return value;
  const parent = navigateToParent(document, tokens, pointer);
  const lastToken = tokens[tokens.length - 1];
  const consumed = formatPointer(tokens);
  if (Array.isArray(parent)) {
    if (!ARRAY_INDEX.test(lastToken)) throw new PointerError(`invalid array index: ${lastToken} at ${consumed}`, pointer);
    const index = Number(lastToken);
    if (index >= parent.length) throw new PointerError(`index out of range: ${lastToken} at ${consumed}`, pointer);
    parent[index] = value;
  } else if (parent !== null && typeof parent === 'object') {
    if (!Object.prototype.hasOwnProperty.call(parent, lastToken)) {
      throw new PointerError(`missing property: ${lastToken} at ${consumed}`, pointer);
    }
    setOwn(parent, lastToken, value);
  } else {
    const type = parent === null ? 'null' : typeof parent;
    throw new PointerError(`cannot index into ${type} at ${consumed}`, pointer);
  }
  return document;
}

/**
 * Throw when `member` is absent from `operation`.
 *
 * @param {object} operation the operation being validated
 * @param {string} member the required member name
 * @param {string} op the operation's `op` value, for the error message
 * @returns {void}
 */
function requireMember(operation, member, op) {
  if (!(member in operation)) throw new Error(`${op} requires a ${member}`);
}

/**
 * Validate and dispatch a single patch operation against the working copy.
 *
 * @param {unknown} document the current working document
 * @param {unknown} operation the operation to apply
 * @returns {unknown} the resulting document
 */
function applyOperation(document, operation) {
  if (typeof operation !== 'object' || operation === null || Array.isArray(operation)) {
    throw new Error('operation must be an object');
  }
  const op = operation.op;
  switch (op) {
    case 'add': {
      requireMember(operation, 'path', op);
      requireMember(operation, 'value', op);
      const tokens = parsePointer(operation.path);
      const value = cloneJSON(operation.value, 'value');
      return addAt(document, tokens, operation.path, value);
    }
    case 'remove': {
      requireMember(operation, 'path', op);
      const tokens = parsePointer(operation.path);
      return removeAt(document, tokens, operation.path);
    }
    case 'replace': {
      requireMember(operation, 'path', op);
      requireMember(operation, 'value', op);
      const tokens = parsePointer(operation.path);
      const value = cloneJSON(operation.value, 'value');
      return replaceAt(document, tokens, operation.path, value);
    }
    case 'move': {
      requireMember(operation, 'path', op);
      requireMember(operation, 'from', op);
      const fromTokens = parsePointer(operation.from);
      const pathTokens = parsePointer(operation.path);
      if (formatPointer(fromTokens) === formatPointer(pathTokens)) {
        resolveTokens(document, fromTokens, operation.from);
        return document;
      }
      if (isProperPrefix(fromTokens, pathTokens)) {
        throw new PointerError('cannot move a value into its own child', operation.from);
      }
      const value = resolveTokens(document, fromTokens, operation.from);
      const afterRemove = removeAt(document, fromTokens, operation.from);
      return addAt(afterRemove, pathTokens, operation.path, value);
    }
    case 'copy': {
      requireMember(operation, 'path', op);
      requireMember(operation, 'from', op);
      const fromTokens = parsePointer(operation.from);
      const pathTokens = parsePointer(operation.path);
      const value = cloneJSON(resolveTokens(document, fromTokens, operation.from), 'value');
      return addAt(document, pathTokens, operation.path, value);
    }
    case 'test': {
      requireMember(operation, 'path', op);
      requireMember(operation, 'value', op);
      const tokens = parsePointer(operation.path);
      const expected = cloneJSON(operation.value, 'value');
      const actual = resolveTokens(document, tokens, operation.path);
      if (!jsonEquals(actual, expected)) throw new Error(`test failed at ${formatPointer(tokens)}`);
      return document;
    }
