{"file_path":"src/order.js","old_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    throw new Error('not implemented');
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    throw new Error('not implemented');
  }
}","new_string":"  /**
   * Validate the structural shape of a command; throws for malformed input.
   *
   * @param {object} command Command to validate.
   */
  #validateStructure(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    this.#validateStructure(command);
    const { type, commandId, at } = command;

    if (this.#appliedCommands.has(commandId)) {
      return { ...this.#appliedCommands.get(commandId), replayed: true };
    }

    const fromState = this.#state;

    if (at < this.#clockMs) {
      const seq = this.#audit.length + 1;
      this.#audit.push({
        seq,
        commandId,
        type,
        at: this.#clockMs,
        from: fromState,
        to: fromState,
        ok: false,
        code: 'CLOCK_REGRESSION',
      });
      const result = {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: 'command arrives before the order clock',
        state: fromState,
        seq,
        replayed: false,
      };
      this.#appliedCommands.set(commandId, result);
      return result;
    }

    this.#clockMs = at;
    const seq = this.#audit.length + 1;

    const fail = (code, message) => {
      this.#audit.push({ seq, commandId, type, at, from: fromState, to: fromState, ok: false, code });
      const result = { ok: false, code, message, state: fromState, seq, replayed: false };
      this.#appliedCommands.set(commandId, result);
      return result;
    };

    if (!allowedTypes(fromState).includes(type)) {
      return fail('BAD_STATE', `${type} is not allowed in state ${fromState}`);
    }

    const rules = FIELD_RULES[type];
    for (const field of rules.strings) {
      if (typeof command[field] !== 'string' || command[field] === '') {
        return fail('MISSING_FIELD', `${field} must be a non-empty string`);
      }
    }
    for (const numRule of rules.numbers) {
      const value = command[numRule.name];
      if (!Number.isInteger(value) || value < numRule.min) {
        return fail('BAD_AMOUNT', `${numRule.name} must be an integer no less than ${numRule.min}`);
      }
    }

    switch (type) {
      case 'addItem':
        if (this.#items.has(command.sku)) return fail('DUPLICATE_SKU', `sku ${command.sku} is already present`);
        break;
      case 'removeItem':
        if (!this.#items.has(command.sku)) return fail('NO_SUCH_ITEM', `sku ${command.sku} is not present`);
        break;
      case 'pay':
        if (this.#items.size === 0) return fail('EMPTY_ORDER', 'cannot pay an order with no items');
        if (command.amountCents !== this.totalCents) return fail('AMOUNT_MISMATCH', 'amount does not match the total');
        break;
      case 'refund':
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return fail('REFUND_TOO_LARGE', 'refund exceeds the amount still owed');
        }
        break;
      default:
        break;
    }

    let toState = fromState;
    switch (type) {
      case 'addItem':
        this.#items.set(command.sku, { sku: command.sku, qty: command.qty, unitPriceCents: command.unitPriceCents });
        toState = 'created';
        break;
      case 'removeItem':
        this.#items.delete(command.sku);
        toState = 'created';
        break;
      case 'pay':
        this.#paidCents = command.amountCents;
        toState = 'paid';
        break;
      case 'pack':
        toState = 'packed';
        break;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        toState = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = at;
        toState = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        toState = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        toState = this.#refundedCents === this.#paidCents ? 'refunded' : 'delivered';
        break;
      default:
        break;
    }

    this.#state = toState;
    this.#audit.push({ seq, commandId, type, at, from: fromState, to: toState, ok: true });
    const result = { ok: true, state: toState, seq, replayed: false };
    this.#appliedCommands.set(commandId, result);
    return result;
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}"}

