import { UriTemplateError, parse } from './parse.js';

const OPERATOR_TABLE = {
  '': { prefix: '', separator: ',', named: false, ifEmpty: '', reservedEncode: false },
  '+': { prefix: '', separator: ',', named: false, ifEmpty: '', reservedEncode: true },
  '#': { prefix: '#', separator: ',', named: false, ifEmpty: '', reservedEncode: true },
  '.': { prefix: '.', separator: '.', named: false, ifEmpty: '', reservedEncode: false },
  '/': { prefix: '/', separator: '/', named: false, ifEmpty: '', reservedEncode: false },
  ';': { prefix: ';', separator: ';', named: true, ifEmpty: '', reservedEncode: false },
  '?': { prefix: '?', separator: '&', named: true, ifEmpty: '=', reservedEncode: false },
  '&': { prefix: '&', separator: '&', named: true, ifEmpty: '=', reservedEncode: false },
};

const RESERVED_CHARS = ":/?#[]@!$&'()*+,;=";

function isUnreservedChar(char) {
  return /^[A-Za-z0-9\-._~]$/.test(char);
}

function isReservedChar(char) {
  return RESERVED_CHARS.includes(char);
}

function percentEncodeCodePoint(codePoint) {
  const char = String.fromCodePoint(codePoint);
  const bytes = Buffer.from(char, 'utf8');
  return Array.from(bytes)
    .map((byte) => `%${byte.toString(16).toUpperCase().padStart(2, '0')}`)
    .join('');
}

/**
 * Encode a string keeping unreserved chars, reserved chars and existing
 * percent-triplets, percent-encoding everything else as UTF-8 bytes.
 *
 * @param {string} str text to encode
 * @returns {string} encoded text
 */
function encodeReserved(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    if (str[i] === '%' && /^[0-9A-Fa-f]{2}$/.test(str.slice(i + 1, i + 3))) {
      result += str.slice(i, i + 3);
      i += 3;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    if (isUnreservedChar(char) || isReservedChar(char)) {
      result += char;
    } else {
      result += percentEncodeCodePoint(codePoint);
    }
    i += char.length;
  }
  return result;
}

/**
 * Encode a string keeping only unreserved chars, percent-encoding everything
 * else (including reserved chars and existing `%`).
 *
 * @param {string} str text to encode
 * @returns {string} encoded text
 */
function encodeUnreservedOnly(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    const codePoint = str.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    if (isUnreservedChar(char)) {
      result += char;
    } else {
      result += percentEncodeCodePoint(codePoint);
    }
    i += char.length;
  }
  return result;
}

function encodeValue(str, reservedEncode) {
  return reservedEncode ? encodeReserved(str) : encodeUnreservedOnly(str);
}

function scalarToString(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

/**
 * Compute the pieces contributed by a single variable binding.
 *
 * @param {{ name: string, explode: boolean, maxLength: (number|null) }} spec variable spec
 * @param {Record<string, unknown>} variables the bound values
 * @param {{ named: boolean, ifEmpty: string, reservedEncode: boolean }} config operator config
 * @returns {string[]} pieces, empty when the variable contributes nothing
 */
function pieceFor(spec, variables, config) {
  const { name, explode, maxLength } = spec;
  if (!Object.prototype.hasOwnProperty.call(variables, name)) return [];
  const value = variables[name];
  if (value === null || value === undefined) return [];

  if (Array.isArray(value)) {
    const members = value.filter((item) => item !== null && item !== undefined);
    if (members.length === 0) return [];
    if (maxLength !== null) throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);

    if (explode) {
      return members.map((item) => {
        const encoded = encodeValue(scalarToString(item, name), config.reservedEncode);
        if (config.named) return encoded === '' ? `${name}${config.ifEmpty}` : `${name}=${encoded}`;
        return encoded;
      });
    }

    const joined = members.map((item) => encodeValue(scalarToString(item, name), config.reservedEncode)).join(',');
    if (config.named) return [joined === '' ? `${name}${config.ifEmpty}` : `${name}=${joined}`];
    return [joined];
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).filter(([, v]) => v !== null && v !== undefined);
    if (entries.length === 0) return [];
    if (maxLength !== null) throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);

    if (explode) {
      return entries.map(([key, val]) => {
        const encodedKey = encodeValue(key, config.reservedEncode);
        const encodedVal = encodeValue(scalarToString(val, name), config.reservedEncode);
        if (config.named && encodedVal === '') return `${encodedKey}${config.ifEmpty}`;
        return `${encodedKey}=${encodedVal}`;
      });
    }

    const flat = entries.flatMap(([key, val]) => [
      encodeValue(key, config.reservedEncode),
      encodeValue(scalarToString(val, name), config.reservedEncode),
    ]);
    const joined = flat.join(',');
    if (config.named) return [joined === '' ? `${name}${config.ifEmpty}` : `${name}=${joined}`];
    return [joined];
  }

  const asString = truncate(scalarToString(value, name), maxLength);
  const encoded = encodeValue(asString, config.reservedEncode);
  if (config.named) return [encoded === '' ? `${name}${config.ifEmpty}` : `${name}=${encoded}`];
  return [encoded];
}

/**
 * Expand a single expression part.
 *
 * @param {{ operator: string, variables: object[] }} expression the expression part
 * @param {Record<string, unknown>} variables the bound values
 * @returns {string} the expanded text for this expression, `''` if nothing contributes
 */
function expandExpression(expression, variables) {
  const config = OPERATOR_TABLE[expression.operator];
  const pieces = expression.variables.flatMap((spec) => pieceFor(spec, variables, config));
  if (pieces.length === 0) return '';
  return config.prefix + pieces.join(config.separator);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  const parts = parse(template);
  if (variables === null || typeof variables !== 'object') {
    throw new UriTemplateError('variables must be an object');
  }

  let result = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeReserved(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }
  return result;
}
"}

