import { PointerError, formatPointer, parsePointer, resolve } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

/**
 * Deep-copy JSON data, verifying it is JSON along the way.
 *
 * @param {unknown} value candidate JSON data
 * @param {string} label word to use in the "is not JSON data" message
 * @returns {unknown} an independent deep copy
 */
function cloneJson(value, label) {
  if (value === null) return null;
  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') return value;
  if (Array.isArray(value)) return value.map((item) => cloneJson(item, label));
  if (type === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = cloneJson(value[key], label);
    }
    return result;
  }
  throw new Error(`${label} is not JSON data`);
}

/**
 * Navigate to the parent container and final token for a non-empty pointer.
 *
 * @param {unknown} document root document
 * @param {string[]} tokens decoded reference tokens, at least one
 * @param {string} pointer the original pointer text, for error reporting
 * @returns {{ container: unknown, token: string }}
 */
function locateParent(document, tokens, pointer) {
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const container = resolve(document, parentPointer);
  return { container, token: tokens[tokens.length - 1] };
}

/**
 * Insert or overwrite a value at a pointer within a document already
 * validated to exist up to the parent.
 *
 * @param {unknown} document root document
 * @param {string} pointer target location
 * @param {unknown} value value to place, already cloned
 * @returns {unknown} the resulting document
 */
function addAt(document, pointer, value) {
  const tokens = parsePointer(pointer);
  if (tokens.length === 0) return value;
  const { container, token } = locateParent(document, tokens, pointer);
  if (Array.isArray(container)) {
    if (token === '-') {
      container.push(value);
    } else {
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        throw new PointerError(`invalid array index: ${token} at ${pointer}`, pointer);
      }
      const index = Number(token);
      if (index > container.length) {
        throw new PointerError(`index out of range: ${token} at ${pointer}`, pointer);
      }
      container.splice(index, 0, value);
    }
  } else if (container !== null && typeof container === 'object') {
    container[token] = value;
  } else {
    const typeName = container === null ? 'null' : typeof container;
    const parentPointer = formatPointer(tokens.slice(0, -1));
    throw new PointerError(`cannot index into ${typeName} at ${parentPointer}`, pointer);
  }
  return document;
}

/**
 * Remove the value at a pointer, requiring it to exist.
 *
 * @param {unknown} document root document
 * @param {string} pointer target location
 * @returns {unknown} the removed value
 */
function removeAt(document, pointer) {
  if (pointer === '') {
    throw new PointerError('cannot remove the whole document', pointer);
  }
  const tokens = parsePointer(pointer);
  resolve(document, pointer);
  const { container, token } = locateParent(document, tokens, pointer);
  if (Array.isArray(container)) {
    const index = Number(token);
    const removed = container[index];
    container.splice(index, 1);
    return removed;
  }
  const removed = container[token];
  delete container[token];
  return removed;
}

/**
 * Compare two JSON values structurally: object members in any order, array
 * elements in order, no type coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether the values are equal as JSON
 */
function jsonEqual(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    return a.every((item, i) => jsonEqual(item, b[i]));
  }
  if (a !== null && b !== null && typeof a === 'object' && typeof b === 'object') {
    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) return false;
    return aKeys.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEqual(a[key], b[key]));
