  if (from.length >= path.length) return false;
  return from.every((token, i) => token === path[i]);
}

/**
 * Validate the shape of a single operation before it runs.
 *
 * @param {unknown} operation candidate operation
 */
function validateOperation(operation) {
  if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) {
    throw new Error('operation must be an object');
  }
  const { op } = operation;
  if (!['add', 'remove', 'replace', 'move', 'copy', 'test'].includes(op)) {
    throw new Error(`unknown operation: ${op}`);
  }
  if (typeof operation.path !== 'string') {
    throw new Error(`${op} requires a path`);
  }
  if ((op === 'move' || op === 'copy') && typeof operation.from !== 'string') {
    throw new Error(`${op} requires a from`);
  }
  if ((op === 'add' || op === 'replace' || op === 'test') && !('value' in operation)) {
    throw new Error(`${op} requires a value`);
  }
  // path/from must be valid pointer text
  parsePointer(operation.path);
  if (typeof operation.from === 'string') parsePointer(operation.from);
}

/**
 * Apply a single already-validated operation to the working document.
 *
 * @param {unknown} document working document, mutated in place
 * @param {object} operation the operation
 * @returns {unknown} the resulting document
 */
function applyOperation(document, operation) {
  const { op, path } = operation;
  switch (op) {
    case 'add': {
      const value = cloneJson(operation.value, 'value');
      return addAt(document, path, value);
    }
    case 'remove': {
      removeAt(document, path);
      return document;
    }
    case 'replace': {
      const value = cloneJson(operation.value, 'value');
      if (path === '') return value;
      resolve(document, path);
      removeAt(document, path);
      return addAt(document, path, value);
    }
    case 'move': {
      const fromTokens = parsePointer(operation.from);
      const pathTokens = parsePointer(path);
      if (formatPointer(fromTokens) === formatPointer(pathTokens)) {
        resolve(document, operation.from);
        return document;
      }
      if (isProperPrefix(fromTokens, pathTokens)) {
        throw new Error('cannot move a value into its own child');
      }
      const value = removeAt(document, operation.from);
      return addAt(document, path, value);
    }
    case 'copy': {
      const value = cloneJson(resolve(document, operation.from), 'value');
      return addAt(document, path, value);
    }
    case 'test': {
      const actual = resolve(document, path);
      if (!jsonEqual(actual, operation.value)) {
        throw new Error(`test failed at ${path}`);
      }
      return document;
    }
    default:
      throw new Error(`unknown operation: ${op}`);
  }
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!Array.isArray(operations)) {
    throw new Error('patch must be an array');
  }
  for (const operation of operations) {
    validateOperation(operation);
  }

  let working = cloneJson(document, 'document');

  for (let index = 0; index < operations.length; index += 1) {
    try {
      working = applyOperation(working, operations[index]);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, index, { cause: error });
      }
      throw new PatchError(error.message, index);
    }
  }

  return working;
}
