{"file_path":"src/expand.js","content":"/** URI template expansion following the operator table. */

import { UriTemplateError, parse } from './parse.js';

const UNRESERVED = /[A-Za-z0-9\-._~]/;
const RESERVED = /[:/?#[\]@!$&'()*+,;=]/;

/** Percent-encode a code point's UTF-8 bytes, uppercase. */
function encodeCodePoint(charStr) {
  const bytes = Buffer.from(charStr, 'utf8');
  let out = '';
  for (const byte of bytes) out += `%${byte.toString(16).toUpperCase().padStart(2, '0')}`;
  return out;
}

/** Keep unreserved and reserved characters and existing percent-triplets; encode the rest. */
function encodeAllowReserved(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    const ch = str[i];
    if (ch === '%' && /^[0-9A-Fa-f]{2}$/.test(str.slice(i + 1, i + 3))) {
      result += str.slice(i, i + 3);
      i += 3;
      continue;
    }
    if (UNRESERVED.test(ch) || RESERVED.test(ch)) {
      result += ch;
      i += 1;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const charStr = String.fromCodePoint(codePoint);
    result += encodeCodePoint(charStr);
    i += charStr.length;
  }
  return result;
}

/** Keep only unreserved characters; encode everything else, including existing percent-triplets. */
function encodeUnreservedOnly(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    const ch = str[i];
    if (UNRESERVED.test(ch)) {
      result += ch;
      i += 1;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const charStr = String.fromCodePoint(codePoint);
    result += encodeCodePoint(charStr);
    i += charStr.length;
  }
  return result;
}

const OPERATOR_CONFIG = {
  '': { prefix: '', sep: ',', named: false, allowReserved: false, empty: '' },
  '+': { prefix: '', sep: ',', named: false, allowReserved: true, empty: '' },
  '#': { prefix: '#', sep: ',', named: false, allowReserved: true, empty: '' },
  '.': { prefix: '.', sep: '.', named: false, allowReserved: false, empty: '' },
  '/': { prefix: '/', sep: '/', named: false, allowReserved: false, empty: '' },
  ';': { prefix: ';', sep: ';', named: true, allowReserved: false, empty: '' },
  '?': { prefix: '?', sep: '&', named: true, allowReserved: false, empty: '=' },
  '&': { prefix: '&', sep: '&', named: true, allowReserved: false, empty: '=' },
};

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

function scalarToString(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

/** Render one variable's contribution to an expression, as an array of pieces. */
function renderVariable(spec, value, config) {
  const encode = config.allowReserved ? encodeAllowReserved : encodeUnreservedOnly;

  if (value === undefined || value === null) return [];

  if (Array.isArray(value)) {
    const items = value.filter((item) => item !== null && item !== undefined);
    if (items.length === 0) return [];
    const encodedItems = items.map((item) => encode(scalarToString(item, spec.name)));

    if (spec.explode) {
      return encodedItems.map((encoded) => {
        if (config.named) {
          return encoded === '' ? `${spec.name}${config.empty}` : `${spec.name}=${encoded}`;
        }
        return encoded;
      });
    }

    const joined = encodedItems.join(',');
    if (config.named) {
      return [joined === '' ? `${spec.name}${config.empty}` : `${spec.name}=${joined}`];
    }
    return [joined];
  }

  if (typeof value === 'object') {
    const entries = Object.keys(value)
      .map((key) => [key, value[key]])
      .filter(([, v]) => v !== null && v !== undefined);
    if (entries.length === 0) return [];

    if (spec.explode) {
      return entries.map(([key, v]) => {
        const encodedKey = encode(key);
        const encodedValue = encode(scalarToString(v, spec.name));
        if (config.named) {
          return encodedValue === '' ? `${encodedKey}${config.empty}` : `${encodedKey}=${encodedValue}`;
        }
        return `${encodedKey}=${encodedValue}`;
      });
    }

    const flat = entries.flatMap(([key, v]) => [encode(key), encode(scalarToString(v, spec.name))]);
    const joined = flat.join(',');
    if (config.named) {
      return [joined === '' ? `${spec.name}${config.empty}` : `${spec.name}=${joined}`];
    }
    return [joined];
  }

  // scalar: string, number or boolean (else scalarToString throws)
  const str = scalarToString(value, spec.name);
  const encoded = encode(truncate(str, spec.maxLength));
  if (config.named) {
    return [encoded === '' ? `${spec.name}${config.empty}` : `${spec.name}=${encoded}`];
  }
  return [encoded];
}

function expandExpression(part, variables) {
  const config = OPERATOR_CONFIG[part.operator];
  const pieces = [];

  for (const spec of part.variables) {
    const hasOwn = Object.prototype.hasOwnProperty.call(variables, spec.name);
    const value = hasOwn ? variables[spec.name] : undefined;

    if (spec.maxLength !== null && value !== null && value !== undefined && typeof value === 'object') {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${spec.name}'`);
    }

    pieces.push(...renderVariable(spec, value, config));
  }

  if (pieces.length === 0) return '';
  return config.prefix + pieces.join(config.sep);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  const parts = parse(template);

  if (variables === null || typeof variables !== 'object') {
    throw new UriTemplateError('variables must be an object');
  }

  let result = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeAllowReserved(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }
  return result;
}
"}

