test('matches a snapshot model across random unions, checkpoints, and rollbacks', () => {
  const rnd = mulberry32(0x0f5e7);
  const size = 12;
  const sets = new DisjointSets(size);
  let labels = Array.from({ length: size }, (_, index) => index);
  /** @type {number[][]} */
  const history = [labels.slice()];
  /** @type {number[]} */
  const marks = [];
  let unions = 0;
  const totals = { joined: 0, undone: 0 };

  for (let step = 0; step < 4000; step += 1) {
    const roll = rnd();
    if (roll < 0.5) {
      const a = Math.floor(rnd() * size);
      const b = Math.floor(rnd() * size);
      const joined = labels[a] !== labels[b];
      assert.equal(sets.union(a, b), joined, `union ${a},${b} at step ${step}`);
      if (joined) {
        const from = labels[b];
        const to = labels[a];
        labels = labels.map((label) => (label === from ? to : label));
        unions += 1;
        totals.joined += 1;
        history[unions] = labels.slice();
      }
    } else if (roll < 0.65) {
      const token = sets.checkpoint();
      assert.equal(token, unions, `checkpoint at step ${step}`);
      marks.push(token);
    } else if (roll < 0.8 && marks.length > 0) {
      const token = marks[Math.floor(rnd() * marks.length)];
      totals.undone += unions - token;
      assert.equal(sets.rollback(token), unions - token, `rollback to ${token} at step ${step}`);
      while (marks.length > 0 && marks[marks.length - 1] > token) marks.pop();
      unions = token;
      labels = history[unions].slice();
    } else if (roll < 0.9) {
      const undone = sets.undo();
      assert.equal(undone, unions > 0, `undo at step ${step}`);
      if (undone) {
        unions -= 1;
        labels = history[unions].slice();
        while (marks.length > 0 && marks[marks.length - 1] > unions) marks.pop();
      }
    } else {
      const a = Math.floor(rnd() * size);
      const b = Math.floor(rnd() * size);
      const same = labels[a] === labels[b];
      assert.deepEqual(
        [sets.connected(a, b), sets.find(a) === sets.find(b), sets.sizeOf(a)],
        [same, same, labels.filter((label) => label === labels[a]).length],
        `probe ${a},${b} at step ${step}`,
      );
    }
    const expected = groupsOf(labels);
    assert.deepEqual([sets.components, sets.groups()], [expected.length, expected], `state at step ${step}`);
    assert.ok(expected.find((group) => group.includes(0)).includes(sets.find(0)), `root of 0 at step ${step}`);
  }
  assert.ok(totals.joined > 200 && totals.undone > 100, `expected real history pressure, saw ${JSON.stringify(totals)}`);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { componentsWithAlternatives, minimumSpanningForest } from '../src/kruskal.js';

test('builds a minimum spanning tree in weight order', () => {
  const edges = [[0, 1, 1], [1, 2, 2], [0, 2, 2], [3, 4, 1], [2, 3, 5], [0, 3, 7]];
  assert.deepEqual(minimumSpanningForest(5, edges), {
    edges: [[0, 1, 1], [3, 4, 1], [0, 2, 2], [2, 3, 5]],
    weight: 9,
    components: 1,
  });
  assert.deepEqual(minimumSpanningForest(5, []), { edges: [], weight: 0, components: 5 });
  assert.deepEqual(minimumSpanningForest(0, []), { edges: [], weight: 0, components: 0 });
});

test('leaves a forest when the graph is disconnected and ignores useless edges', () => {
  assert.deepEqual(minimumSpanningForest(5, [[0, 1, 3], [2, 3, 4]]), {
    edges: [[0, 1, 3], [2, 3, 4]],
    weight: 7,
    components: 3,
  });
  assert.deepEqual(minimumSpanningForest(3, [[0, 0, 1], [0, 1, 2], [1, 0, 3]]), {
    edges: [[0, 1, 2]],
    weight: 2,
    components: 2,
  });
  assert.deepEqual(minimumSpanningForest(4, [[2, 3, 5], [0, 1, 5], [1, 2, 5], [0, 3, 5]]).edges, [
    [0, 1, 5], [0, 3, 5], [1, 2, 5],
  ]);
  assert.deepEqual(minimumSpanningForest(3, [[0, 1, -2], [1, 2, -3]]).weight, -5);
});

test('alternatives are measured independently of one another', () => {
  const result = componentsWithAlternatives(6, [[0, 1, 1]], [
    [[2, 3, 1]],
    [[2, 3, 1], [3, 4, 1]],
    [[0, 1, 9]],
    [],
  ]);
  assert.deepEqual(result, { base: 5, alternatives: [4, 3, 5, 5] });
  assert.deepEqual(componentsWithAlternatives(3, [], []), { base: 3, alternatives: [] });
  assert.deepEqual(
    componentsWithAlternatives(4, [[0, 1, 1], [2, 3, 1]], [[[1, 2, 1]], [[1, 2, 1]], [[0, 3, 1]]]),
    { base: 2, alternatives: [1, 1, 1] },
  );
});

test('rejects malformed edges', () => {
  const bad = [
    [() => minimumSpanningForest(3, 'edges'), 'TypeError', 'edges must be an array'],
    [() => minimumSpanningForest(3, [[0, 1]]), 'TypeError', 'edge must be [u, v, weight]'],
    [() => minimumSpanningForest(3, [{ u: 0, v: 1, w: 2 }]), 'TypeError', 'edge must be [u, v, weight]'],
    [() => minimumSpanningForest(3, [[0, 1, '2']]), 'TypeError', 'weight must be a finite number'],
    [() => minimumSpanningForest(3, [[0, 1, Number.POSITIVE_INFINITY]]), 'TypeError', 'weight must be a finite number'],
    [() => minimumSpanningForest(3, [[0, 4, 1]]), 'RangeError', 'element out of range: 4'],
    [() => minimumSpanningForest(3, [[-1, 0, 1]]), 'RangeError', 'element out of range: -1'],
    [() => componentsWithAlternatives(3, [], 'nope'), 'TypeError', 'alternatives must be an array'],
    [() => componentsWithAlternatives(3, [], [[[0, 9, 1]]]), 'RangeError', 'element out of range: 9'],
  ];
  for (const [call, name, message] of bad) assert.throws(call, { name, message }, message);
});

