{"file_path":"src/kruskal.js","content":"/**
 * Spanning-forest and what-if queries built on the rollback-capable
 * disjoint-set structure.
 *
 * An edge is `[u, v, weight]` with element indices and a finite weight.
 */

import { DisjointSets } from './dsu.js';

/**
 * Validates a count value.
 * @param {unknown} count Value to check.
 */
function checkCount(count) {
  if (!Number.isSafeInteger(count) || count < 0) {
    throw new TypeError('count must be a non-negative integer');
  }
}

/**
 * Validates that a value names an element within `0 .. count - 1`.
 * @param {number} count Element count.
 * @param {unknown} element Value to check.
 */
function checkElement(count, element) {
  if (!Number.isSafeInteger(element) || element < 0 || element >= count) {
    throw new RangeError(`element out of range: ${element}`);
  }
}

/**
 * Validates and normalizes an edge list.
 * @param {number} count Element count.
 * @param {unknown} edges Value to validate.
 * @returns {Array<[number, number, number]>} Validated edges.
 */
function checkEdges(count, edges) {
  if (!Array.isArray(edges)) {
    throw new TypeError('edges must be an array');
  }
  return edges.map((edge) => {
    if (!Array.isArray(edge) || edge.length !== 3) {
      throw new TypeError('edge must be [u, v, weight]');
    }
    const [u, v, weight] = edge;
    if (typeof weight !== 'number' || !Number.isFinite(weight)) {
      throw new TypeError('weight must be a finite number');
    }
    checkElement(count, u);
    checkElement(count, v);
    return [u, v, weight];
  });
}

/**
 * Builds a minimum spanning forest with Kruskal's algorithm, taking edges by
 * weight and breaking ties by the first endpoint and then the second.
 * @param {number} count Element count.
 * @param {unknown} edges Available edges.
 * @returns {{edges: Array<[number, number, number]>, weight: number, components: number}} Chosen edges, their total weight, and the remaining component count.
 */
export function minimumSpanningForest(count, edges) {
  checkCount(count);
  const validated = checkEdges(count, edges);
  const ordered = validated
    .slice()
    .sort((a, b) => a[2] - b[2] || a[0] - b[0] || a[1] - b[1]);
  const sets = new DisjointSets(count);
  const chosen = [];
  let weight = 0;
  for (const edge of ordered) {
    const [u, v, w] = edge;
    if (sets.union(u, v)) {
      chosen.push(edge);
      weight += w;
    }
  }
  return { edges: chosen, weight, components: sets.components };
}

/**
 * Measures how many components remain after each alternative edge set is
 * added on top of a shared base, evaluating each alternative independently by
 * rolling back to the state the base left behind.
 * @param {number} count Element count.
 * @param {unknown} baseEdges Edges applied once, before any alternative.
 * @param {unknown} alternatives Array of edge lists to try one at a time.
 * @returns {{base: number, alternatives: number[]}} Component count for the base and for each alternative.
 */
export function componentsWithAlternatives(count, baseEdges, alternatives) {
  checkCount(count);
  const validatedBase = checkEdges(count, baseEdges);
  if (!Array.isArray(alternatives)) {
    throw new TypeError('alternatives must be an array');
  }
  const validatedAlternatives = alternatives.map((alt) => checkEdges(count, alt));

  const sets = new DisjointSets(count);
  for (const [u, v] of validatedBase) sets.union(u, v);
  const base = sets.components;
  const checkpoint = sets.checkpoint();

  const results = [];
  for (const alt of validatedAlternatives) {
    for (const [u, v] of alt) sets.union(u, v);
    results.push(sets.components);
    sets.rollback(checkpoint);
  }

  return { base, alternatives: results };
}
"}

