{"file_path":"src/resolve.js","old_string":"export function resolve(registry, rootDeps) {
  throw new Error('not implemented');
}","new_string":"/** Validate the registry structure, throwing BAD_REGISTRY, BAD_VERSION or BAD_DEPENDENCIES. */
function validateRegistry(registry) {
  if (typeof registry !== 'object' || registry === null || Array.isArray(registry)) {
    throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  }
  for (const [name, versions] of Object.entries(registry)) {
    if (typeof versions !== 'object' || versions === null || Array.isArray(versions)) {
      throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    }
    for (const [version, metadata] of Object.entries(versions)) {
      parseVersion(version);
      if (typeof metadata !== 'object' || metadata === null || Array.isArray(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${version}`);
      }
      if (metadata.deps !== undefined) {
        if (typeof metadata.deps !== 'object' || metadata.deps === null || Array.isArray(metadata.deps)) {
          throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${version} must be an object`);
        }
        for (const range of Object.values(metadata.deps)) {
          parseRange(range);
        }
      }
    }
  }
}

/** Validate the root dependency map, throwing BAD_DEPENDENCIES or BAD_RANGE. */
function validateRootDeps(rootDeps) {
  if (typeof rootDeps !== 'object' || rootDeps === null || Array.isArray(rootDeps)) {
    throw new ResolveError('BAD_DEPENDENCIES', 'root dependencies must be an object');
  }
  for (const range of Object.values(rootDeps)) {
    parseRange(range);
  }
}

export function resolve(registry, rootDeps) {
  validateRegistry(registry);
  validateRootDeps(rootDeps);

  const constraints = new Map(); // name -> [{ range, via }]
  const selected = new Map(); // name -> { version, chain }
  const pending = new Set();
  const order = [];

  for (const name of Object.keys(rootDeps).sort()) {
    constraints.set(name, [{ range: rootDeps[name], via: '<root>' }]);
    pending.add(name);
  }

  function addConstraint(name, range, via) {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push({ range, via });
  }

  function raiseConflict(name) {
    const available = registry[name] ? Object.keys(registry[name]).sort(compareVersions) : [];
    throw new ConflictError(name, constraints.get(name) ?? [], available);
  }

  while (pending.size > 0) {
    const name = [...pending].sort()[0];
    pending.delete(name);

    if (!(name in registry)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }

    const allVersions = Object.keys(registry[name]);
    const packageConstraints = constraints.get(name) ?? [];

    let candidates = allVersions;
    for (const { range } of packageConstraints) {
      const matched = candidates.filter((version) => {
        try {
          return require('./semver.js');
        } catch {
          return false;
        }
      });
      candidates = matched;
    }

    // Recompute properly using satisfies-like filtering via parseRange comparators.
    candidates = allVersions;
    for (const { range } of packageConstraints) {
      const comparators = parseRange(range);
      candidates = candidates.filter((version) => {
        for (const { operator, version: bound } of comparators) {
          const cmp = compareVersions(version, bound);
          if (operator === '>=' && cmp < 0) return false;
          if (operator === '<=' && cmp > 0) return false;
          if (operator === '>' && cmp <= 0) return false;
          if (operator === '<' && cmp >= 0) return false;
          if (operator === '=' && cmp !== 0) return false;
        }
        return true;
      });
    }

    if (selected.has(name)) {
      // Already selected: verify it still satisfies the newest constraint(s).
      const current = selected.get(name).version;
      if (!candidates.includes(current)) {
        raiseConflict(name);
      }
      continue;
    }

    if (candidates.length === 0) {
      raiseConflict(name);
    }

    let best = candidates[0];
    for (const version of candidates) {
      if (compareVersions(version, best) > 0) best = version;
    }

    const origin = packageConstraints[0].via;
    const chain = `${origin} > ${name}@${best}`;
    selected.set(name, { version: best, chain });
    order.push(name);

    const metadata = registry[name][best];
    const deps = metadata.deps ?? {};
    for (const depName of Object.keys(deps).sort()) {
      const range = deps[depName];
      addConstraint(depName, range, chain);
      if (!selected.has(depName)) {
        pending.add(depName);
      } else {
        pending.add(depName);
      }
    }
  }

  const resolved = {};
  for (const name of [...selected.keys()].sort()) {
    resolved[name] = selected.get(name).version;
  }
  return { resolved, order };
}"}

