{"file_path":"src/order.js","old_string":"/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 *
 * Construction and the read side exist; nothing applies commands yet.
 */","new_string":"/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */

import { COMMAND_TYPES, allowedTypes } from './machine.js';

/** @returns {boolean} True for a non-empty string. */
function isNonEmptyString(value) {
  return typeof value === 'string' && value !== '';
}

/** @returns {boolean} True for an integer at least `min`. */
function isIntAtLeast(value, min) {
  return Number.isInteger(value) && value >= min;
}

/**
 * Validate the fields a command's own type requires.
 *
 * @param {object} command Command to check.
 * @returns {string|null} A rejection code, or null if the fields are fine.
 */
function validateFields(command) {
  switch (command.type) {
    case 'addItem':
      if (!isNonEmptyString(command.sku)) return 'MISSING_FIELD';
      if (!isIntAtLeast(command.qty, 1)) return 'BAD_AMOUNT';
      if (!isIntAtLeast(command.unitPriceCents, 0)) return 'BAD_AMOUNT';
      return null;
    case 'removeItem':
      if (!isNonEmptyString(command.sku)) return 'MISSING_FIELD';
      return null;
    case 'pay':
      if (!isIntAtLeast(command.amountCents, 0)) return 'BAD_AMOUNT';
      return null;
    case 'ship':
      if (!isNonEmptyString(command.carrier)) return 'MISSING_FIELD';
      if (!isNonEmptyString(command.tracking)) return 'MISSING_FIELD';
      return null;
    case 'cancel':
      if (!isNonEmptyString(command.reason)) return 'MISSING_FIELD';
      return null;
    case 'refund':
      if (!isIntAtLeast(command.amountCents, 1)) return 'BAD_AMOUNT';
      return null;
    default:
      return null;
  }
}"}

