      case 'addItem': {
        if (this.#items.has(command.sku)) {
          return this.#reject(command, at, from, from, 'DUPLICATE_SKU', `sku already present: ${command.sku}`);
        }
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return this.#accept(command, at, from, from);
      }
      case 'removeItem': {
        if (!this.#items.has(command.sku)) {
          return this.#reject(command, at, from, from, 'NO_SUCH_ITEM', `no such item: ${command.sku}`);
        }
        this.#items.delete(command.sku);
        return this.#accept(command, at, from, from);
      }
      case 'pay': {
        if (this.#items.size === 0) {
          return this.#reject(command, at, from, from, 'EMPTY_ORDER', 'an order with no items cannot be paid');
        }
        if (command.amountCents !== this.totalCents) {
          return this.#reject(command, at, from, from, 'AMOUNT_MISMATCH', 'payment does not match the order total');
        }
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        return this.#accept(command, at, from, 'paid');
      }
      case 'pack': {
        this.#state = 'packed';
        return this.#accept(command, at, from, 'packed');
      }
      case 'ship': {
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        return this.#accept(command, at, from, 'shipped');
      }
      case 'deliver': {
        this.#deliveredAt = at;
        this.#state = 'delivered';
        return this.#accept(command, at, from, 'delivered');
      }
      case 'cancel': {
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        return this.#accept(command, at, from, 'cancelled');
      }
      case 'refund': {
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return this.#reject(command, at, from, from, 'REFUND_TOO_LARGE', 'refund exceeds the amount available');
