        this.#state = 'packed';
        return this.#accept(command, at, from, 'packed');
      }
      case 'ship': {
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        return this.#accept(command, at, from, 'shipped');
      }
      case 'deliver': {
        this.#deliveredAt = at;
        this.#state = 'delivered';
        return this.#accept(command, at, from, 'delivered');
      }
      case 'cancel': {
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        return this.#accept(command, at, from, 'cancelled');
      }
      case 'refund': {
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return this.#reject(command, at, from, from, 'REFUND_TOO_LARGE', 'refund exceeds the amount available');
        }
        this.#refundedCents += command.amountCents;
        const to = this.#refundedCents >= this.#paidCents ? 'refunded' : from;
        this.#state = to;
        return this.#accept(command, at, from, to);
      }
      default:
        throw new TypeError(`unknown command type: ${command.type}`);
    }
  }

  /**
   * Append a rejection audit entry and record it for replay.
   *
   * @param {object} command Command being applied.
   * @param {number} at Timestamp to stamp on the entry.
   * @param {string} from State before the command.
   * @param {string} to State after the command (equals `from` for a rejection).
   * @param {string} code Rejection code.
   * @param {string} message Explanation of the rejection.
   * @returns {object} The rejection result.
   */
  #reject(command, at, from, to, code, message) {
    const seq = this.#audit.length + 1;
    this.#audit.push({
      seq,
      commandId: command.commandId,
      type: command.type,
      at,
      from,
      to,
      ok: false,
      code,
    });
    const result = { ok: false, code, message, state: to, seq, replayed: false };
    this.#seen.set(command.commandId, { ok: false, code, message, state: to, seq });
    return result;
  }

  /**
   * Append a success audit entry and record it for replay.
   *
   * @param {object} command Command being applied.
   * @param {number} at Timestamp to stamp on the entry.
   * @param {string} from State before the command.
   * @param {string} to State after the command.
   * @returns {object} The success result.
   */
  #accept(command, at, from, to) {
    const seq = this.#audit.length + 1;
    this.#audit.push({
      seq,
      commandId: command.commandId,
      type: command.type,
      at,
      from,
      to,
      ok: true,
    });
    const result = { ok: true, state: to, seq, replayed: false };
    this.#seen.set(command.commandId, { ok: true, state: to, seq });
    return result;
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}"}

