/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);

function isDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '9';
}

function isIdentStart(ch) {
  return ch !== undefined && ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || ch === '_');
}

function isIdentPart(ch) {
  return isIdentStart(ch) || isDigit(ch);
}

/**
 * Parse a numeric literal starting at `start`, which must begin with a digit
 * or with a `.` followed by a digit.
 *
 * @param {string} input source text
 * @param {number} start index of the first character of the literal
 * @returns {{ value: number, end: number }} parsed value and the index just past it
 */
function readNumber(input, start) {
  let i = start;
  let sawDigits = false;

  while (isDigit(input[i])) {
    i += 1;
    sawDigits = true;
  }

  if (input[i] === '.') {
    i += 1;
    const fracStart = i;
    while (isDigit(input[i])) i += 1;
    if (i === fracStart) {
      throw new ExprError('malformed number', start);
    }
    sawDigits = true;
  }

  if (input[i] === 'e' || input[i] === 'E') {
    i += 1;
    if (input[i] === '+' || input[i] === '-') i += 1;
    const digitsStart = i;
    while (isDigit(input[i])) i += 1;
    if (i === digitsStart) {
      throw new ExprError('malformed number', start);
    }
  }

  const trailing = input[i];
  if (trailing !== undefined && (isDigit(trailing) || trailing === '.' || isIdentStart(trailing))) {
    throw new ExprError('malformed number', start);
  }

  const text = input.slice(start, i);
  return { value: Number(text), end: i };
}

/**
 * Return the full code point starting at `index` (handling surrogate pairs)
 * along with its UTF-16 length.
 *
 * @param {string} input source text
 * @param {number} index position of the first UTF-16 unit
 * @returns {{ char: string, length: number }}
 */
function readCodePoint(input, index) {
  const cp = input.codePointAt(index);
  const char = String.fromCodePoint(cp);
  return { char, length: char.length };
}

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  let i = 0;
  const n = input.length;

  while (i < n) {
    const ch = input[i];

    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f') {
      i += 1;
      continue;
    }

    if (isDigit(ch) || (ch === '.' && isDigit(input[i + 1]))) {
      const start = i;
      const { value, end } = readNumber(input, start);
      tokens.push({ type: 'number', value, index: start });
      i = end;
      continue;
    }

    if (isIdentStart(ch)) {
      const start = i;
      let j = i + 1;
      while (isIdentPart(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }

    if (OPERATORS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === ',') {
      tokens.push({ type: 'comma', value: ch, index: i });
      i += 1;
      continue;
    }

    const { char } = readCodePoint(input, i);
    throw new ExprError(`unexpected character '${char}' at ${i}`, i);
  }

  return tokens;
}
"}

