import { ExprError, tokenize } from './tokenize.js';

const ADDITIVE = new Set(['+', '-']);
const MULTIPLICATIVE = new Set(['*', '/', '%']);

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function endIndex() {
    return input.length;
  }

  function describe(token) {
    if (token.type === 'number') return String(token.value);
    return String(token.value);
  }

  function expect(type) {
    const token = peek();
    if (token === undefined) {
      throw new ExprError(`unexpected end of input at ${endIndex()}`, endIndex());
    }
    if (token.type !== type) {
      throw new ExprError(`unexpected token '${describe(token)}' at ${token.index}`, token.index);
    }
    pos += 1;
    return token;
  }

  function parsePrimary() {
    const token = peek();
    if (token === undefined) {
      throw new ExprError(`unexpected end of input at ${endIndex()}`, endIndex());
    }

    if (token.type === 'number') {
      pos += 1;
      return { type: 'number', value: token.value, index: token.index };
    }

    if (token.type === 'name') {
      pos += 1;
      const next = peek();
      if (next !== undefined && next.type === 'lparen') {
        pos += 1;
        const args = [];
        if (peek() !== undefined && peek().type === 'rparen') {
          pos += 1;
        } else {
          for (;;) {
            args.push(parseExpr());
            const after = peek();
            if (after === undefined) {
              throw new ExprError(`unexpected end of input at ${endIndex()}`, endIndex());
            }
            if (after.type === 'comma') {
              pos += 1;
              continue;
            }
            if (after.type === 'rparen') {
              pos += 1;
              break;
            }
            throw new ExprError(`unexpected token '${describe(after)}' at ${after.index}`, after.index);
          }
        }
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    if (token.type === 'lparen') {
      pos += 1;
      const inner = parseExpr();
      const next = peek();
      if (next === undefined || next.type !== 'rparen') {
        const missingAt = next === undefined ? endIndex() : next.index;
        throw new ExprError(`missing closing parenthesis at ${missingAt}`, missingAt);
      }
      pos += 1;
      return inner;
    }

    throw new ExprError(`unexpected token '${describe(token)}' at ${token.index}`, token.index);
  }

  function parsePower() {
    const base = parsePrimary();
    const token = peek();
    if (token !== undefined && token.type === 'operator' && token.value === '^') {
      pos += 1;
      const right = parseUnary();
      return { type: 'binary', op: '^', left: base, right, index: token.index };
    }
    return base;
  }

  function parseUnary() {
    const token = peek();
    if (token !== undefined && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      pos += 1;
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parsePower();
  }

  function parseTerm() {
    let left = parseUnary();
    for (;;) {
      const token = peek();
      if (token !== undefined && token.type === 'operator' && MULTIPLICATIVE.has(token.value)) {
        pos += 1;
        const right = parseUnary();
        left = { type: 'binary', op: token.value, left, right, index: token.index };
        continue;
      }
      break;
    }
    return left;
  }

  function parseExpr() {
    let left = parseTerm();
    for (;;) {
      const token = peek();
      if (token !== undefined && token.type === 'operator' && ADDITIVE.has(token.value)) {
        pos += 1;
        const right = parseTerm();
        left = { type: 'binary', op: token.value, left, right, index: token.index };
        continue;
      }
      break;
    }
    return left;
  }

  const tree = parseExpr();
  const remaining = peek();
  if (remaining !== undefined) {
    if (remaining.type === 'rparen') {
      throw new ExprError(`unexpected token '${describe(remaining)}' at ${remaining.index}`, remaining.index);
    }
    throw new ExprError(`unexpected token '${describe(remaining)}' at ${remaining.index}`, remaining.index);
  }
  return tree;
}
"}

