const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { arity: 1, fn: (a) => Math.abs(a) },
  sqrt: { arity: 1, fn: (a) => Math.sqrt(a) },
  floor: { arity: 1, fn: (a) => Math.floor(a) },
  ceil: { arity: 1, fn: (a) => Math.ceil(a) },
  round: { arity: 1, fn: (a) => Math.floor(a + 0.5) },
  sign: { arity: 1, fn: (a) => Math.sign(a) },
  pow: { arity: 2, fn: (a, b) => Math.pow(a, b) },
  atan2: { arity: 2, fn: (a, b) => Math.atan2(a, b) },
  min: { arity: -1, fn: (...args) => Math.min(...args) },
  max: { arity: -1, fn: (...args) => Math.max(...args) },
};

function evalNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;

    case 'variable': {
      const name = node.name;
      let value;
      if (Object.prototype.hasOwnProperty.call(env, name)) {
        value = env[name];
      } else if (Object.prototype.hasOwnProperty.call(CONSTANTS, name)) {
        value = CONSTANTS[name];
      } else {
        throw new ExprError(`unknown variable: ${name}`, node.index);
      }
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        throw new ExprError(`variable ${name} is not a finite number`, node.index);
      }
      return value;
    }

    case 'unary': {
      const operand = evalNode(node.operand, env);
      const value = node.op === '-' ? -operand : +operand;
      if (!Number.isFinite(value)) {
        throw new ExprError('non-finite result', node.index);
      }
      return value;
    }

    case 'binary': {
      const left = evalNode(node.left, env);
      const right = evalNode(node.right, env);
      if ((node.op === '/' || node.op === '%') && right === 0) {
        throw new ExprError('division by zero', node.index);
      }
      let value;
      switch (node.op) {
        case '+':
          value = left + right;
          break;
        case '-':
          value = left - right;
          break;
        case '*':
          value = left * right;
          break;
        case '/':
          value = left / right;
          break;
        case '%':
          value = left % right;
          break;
        case '^':
          value = Math.pow(left, right);
          break;
        default:
          throw new Error(`unknown operator: ${node.op}`);
      }
      if (!Number.isFinite(value)) {
        throw new ExprError('non-finite result', node.index);
      }
      return value;
    }

    case 'call': {
      const def = FUNCTIONS[node.name];
      if (!def) {
        throw new ExprError(`unknown function: ${node.name}`, node.index);
      }
      const args = node.args.map((arg) => evalNode(arg, env));
      if (def.arity === -1) {
        if (args.length < 1) {
          throw new ExprError(`function ${node.name} expects at least 1 argument, got ${args.length}`, node.index);
        }
      } else if (args.length !== def.arity) {
        const word = def.arity === 1 ? 'argument' : 'arguments';
        throw new ExprError(`function ${node.name} expects ${def.arity} ${word}, got ${args.length}`, node.index);
      }
      const value = def.fn(...args);
      if (!Number.isFinite(value)) {
        throw new ExprError('non-finite result', node.index);
      }
      return value;
    }

    default:
      throw new Error(`unknown node type: ${node.type}`);
  }
}

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  const tree = parse(input);
  return evalNode(tree, env);
}
