  /**
   * @param {number} count How many elements the structure holds.
   */
  constructor(count) {
    validateCount(count);
    this.#parent = Array.from({ length: count }, (_, index) => index);
    this.#size = new Array(count).fill(1);
    this.#components = count;
    this.#history = [];
  }

  /**
   * Validates an element argument.
   * @param {unknown} element Candidate element.
   * @returns {void}
   */
  #validateElement(element) {
    if (
      typeof element !== 'number' ||
      !Number.isSafeInteger(element) ||
      element < 0 ||
      element >= this.#parent.length
    ) {
      throw new RangeError(`element out of range: ${element}`);
    }
  }

