{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * A real trie: one node per distinct prefix, walked by Unicode code point so
 * a character outside the basic plane is a single step rather than a pair of
 * surrogate halves. Each node keeps a count of the words stored in its
 * subtree (including itself, if it marks the end of a word) so that
 * countPrefix costs only the length of the prefix.
 */

class TrieNode {
  /** @type {Map<string, TrieNode>} */
  children = new Map();

  /** Whether this node marks the end of a stored word. */
  isEnd = false;

  /** Value stored for the word ending here, when isEnd is true. */
  value = undefined;

  /** Number of stored words in this node's subtree, this node included. */
  count = 0;
}

/**
 * Splits a string into an array of single code point strings.
 * @param {string} value String to split.
 * @returns {string[]} Code points, each as a one-character-in-code-point string.
 */
function toCodePoints(value) {
  return [...value];
}

/**
 * Validates that a value is a string, throwing otherwise.
 * @param {unknown} value Value to check.
 * @param {string} label Name to use in the error message.
 * @returns {void}
 */
function assertString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string`);
  }
}

/**
 * Validates a search limit, throwing otherwise.
 * @param {unknown} limit Value to check.
 * @returns {void}
 */
function assertLimit(limit) {
  const ok = limit === Number.POSITIVE_INFINITY || (Number.isSafeInteger(limit) && limit >= 0);
  if (!ok) {
    throw new TypeError('limit must be a non-negative integer');
  }
}

/**
 * Compares two code point strings by their code point value.
 * @param {string} a First code point.
 * @param {string} b Second code point.
 * @returns {number} Negative, zero, or positive.
 */
function compareCodePoints(a, b) {
  return a.codePointAt(0) - b.codePointAt(0);
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#root.count;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    assertString(word, 'word');
    const codePoints = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const cp of codePoints) {
      let child = node.children.get(cp);
      if (!child) {
        child = new TrieNode();
        node.children.set(cp, child);
        this.#nodeCount += 1;
      }
      node = child;
      path.push(node);
    }
    const isNew = !node.isEnd;
    const previous = node.isEnd ? node.value : undefined;
    if (isNew) {
      for (const n of path) n.count += 1;
    }
    node.isEnd = true;
    node.value = value;
    return previous;
  }

  /**
   * Walks to the node for an exact string, without creating anything.
   * @param {string} word String to walk to.
   * @returns {TrieNode | null} Node reached, or null when absent.
   */
  #find(word) {
    let node = this.#root;
    for (const cp of toCodePoints(word)) {
      const child = node.children.get(cp);
      if (!child) return null;
      node = child;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    assertString(word, 'word');
    const node = this.#find(word);
    return node && node.isEnd ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    assertString(word, 'word');
    const node = this.#find(word);
    return Boolean(node && node.isEnd);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    assertString(word, 'word');
    const codePoints = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const cp of codePoints) {
      const child = node.children.get(cp);
      if (!child) return false;
      node = child;
      path.push(node);
    }
    if (!node.isEnd) return false;

    for (const n of path) n.count -= 1;
    node.isEnd = false;
    node.value = undefined;

    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.isEnd || current.children.size > 0) break;
      const parent = path[i - 1];
      parent.children.delete(codePoints[i - 1]);
      this.#nodeCount -= 1;
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    assertString(prefix, 'prefix');
    const node = this.#find(prefix);
    return node ? node.count : 0;
  }

  /**
   * Collects words under a node, in code point order, into an output array.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word prefix accumulated so far.
   * @param {number} limit Maximum number of entries to collect.
   * @param {Array<[string, unknown]>} out Output accumulator.
   * @returns {void}
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.isEnd) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort(compareCodePoints);
    for (const key of keys) {
      this.#collect(node.children.get(key), prefix + key, limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    assertString(prefix, 'prefix');
    assertLimit(limit);
    const node = this.#find(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    assertString(text, 'text');
    let node = this.#root;
    let best = null;
    let word = '';
    if (node.isEnd) best = { word: '', value: node.value };
    for (const cp of toCodePoints(text)) {
      const child = node.children.get(cp);
      if (!child) break;
      node = child;
      word += cp;
      if (node.isEnd) best = { word, value: node.value };
    }
    return best;
  }
}
"}

